<script>(function(){var tabs=document.querySelectorAll('[data-tab]'),panels=document.querySelectorAll('[data-panel]'),meta={identity:['Identitas RT','Informasi utama yang tampil pada header dan halaman publik.','⌂'],home:['Tampilan Beranda','Kelola banner, informasi lingkungan, dan nilai utama yang ditampilkan di halaman beranda.','▧'],stats:['Statistik Agregat','Ringkasan jumlah keluarga dan warga pada website.','▥'],contact:['Kontak & Pengaturan','Atur identitas, tampilan beranda, statistik, dan kontak RT dalam satu tempat.','⚙'],theme:['Tema & Fitur','Warna tampilan dan fitur opsional yang perlu persetujuan pengurus.','◉']};document.querySelectorAll('input[type=color]').forEach(function(i){i.oninput=function(){var b=document.getElementById('theme-preview-btn'),t=document.getElementById('theme-preview-title');if(i.name==='theme_accent'&&b)b.style.background=i.value;if(i.name==='theme_navy'&&t)t.style.color=i.value}});function open(name){tabs.forEach(function(t){t.classList.toggle('active',t.dataset.tab===name)});panels.forEach(function(p){var show=p.dataset.panel===name;p.hidden=!show;p.classList.toggle('active',show)});var item=meta[name]||meta.identity;document.getElementById('settings-hero-title').textContent=item[0];document.getElementById('settings-hero-text').textContent=item[1];document.getElementById('settings-hero-icon').textContent=item[2];try{sessionStorage.setItem('settingsTab',name)}catch(e){}}tabs.forEach(function(t){t.onclick=function(){open(t.dataset.tab)}});document.querySelectorAll('[data-step]').forEach(function(button){button.onclick=function(){var input=button.parentElement.querySelector('input'),next=Math.max(0,(parseInt(input.value,10)||0)+parseInt(button.dataset.step,10));input.value=next;input.dispatchEvent(new Event('change',{bubbles:true}))}});var logo=document.getElementById('settings-logo');if(logo)logo.onchange=function(){var file=logo.files&&logo.files[0],box=document.getElementById('settings-logo-preview');if(!file||!box)return;box.innerHTML='<img alt="Pratinjau logo">';box.querySelector('img').src=URL.createObjectURL(file)};var footer=document.getElementById('footer-banner-input');if(footer)footer.onchange=function(){var file=footer.files&&footer.files[0],preview=document.getElementById('footer-banner-preview');if(file&&preview)preview.src=URL.createObjectURL(file)};var banner=document.getElementById('home-banner-input');if(banner)banner.onchange=function(){var file=banner.files&&banner.files[0],preview=document.getElementById('home-banner-preview');if(file&&preview)preview.src=URL.createObjectURL(file)};try{open(meta[new URLSearchParams(location.search).get('tab')]?new URLSearchParams(location.search).get('tab'):(sessionStorage.getItem('settingsTab')||'identity'))}catch(e){open('identity')}})();</script>
